 public List<string> Names=new List<string>();public List<decimal> Actual=new List<decimal>(),Target=new List<decimal>();public bool Daily;ToolTip tip=new ToolTip();int lastTip=-1;
 public SalesBars(){DoubleBuffered=true;BackColor=Color.White;Height=220;Dock=DockStyle.Fill;}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);if(Names.Count==0)return;var g=e.Graphics;decimal max=Math.Max(1m,Actual.Concat(Target).DefaultIfEmpty(0m).Max());float width=Math.Max(30,Width-190);int h=Math.Max(55,(Height-25)/Names.Count);using(var blue=new SolidBrush(Color.FromArgb(38,124,235)))using(var teal=new SolidBrush(Color.FromArgb(25,167,172)))using(var grey=new SolidBrush(Color.FromArgb(223,229,237)))using(var font=new Font("Segoe UI",9f)){if(!Daily){for(int i=0;i<Names.Count;i++){int y=i*h+8;g.DrawString(Names[i],font,Brushes.Black,5,y+6);float bw=(float)(Target[i]/max)*width,aw=(float)(Actual[i]/max)*width;g.FillRectangle(grey,95,y+5,bw,18);g.FillRectangle(i==2?teal:blue,95,y+5,Math.Max(0,aw),18);string ratio=Target[i]>0?(Actual[i]/Target[i]*100).ToString("N1",CultureInfo.GetCultureInfo("es-AR"))+" %":"Sin objetivo";g.DrawString(ratio,font,Brushes.Black,Width-85,y+6);g.DrawString(Money(Actual[i])+" / "+Money(Target[i])+" · "+(Target[i]>0?(Actual[i]>=Target[i]?"Superado: "+Money(Actual[i]-Target[i]):"Faltan: "+Money(Target[i]-Actual[i])):"Sin objetivo"),font,Brushes.DimGray,95,y+27);}}else {float slot=(Width-60f)/Names.Count;float chartHeight=Height-65;decimal low=Math.Min(0,Actual.Concat(Target).Min());decimal range=max-low;float baseline=8+(float)(max/range)*chartHeight;for(int i=0;i<Names.Count;i++){float x=35+i*slot;float a=(float)(Actual[i]/range)*chartHeight,b=(float)(Target[i]/range)*chartHeight;g.DrawLine(Pens.LightGray,30,baseline,Width-5,baseline);g.FillRectangle(blue,x,baseline-Math.Max(0,a),Math.Max(2,slot*.3f),Math.Abs(a));g.FillRectangle(teal,x+slot*.32f,baseline-Math.Max(0,b),Math.Max(2,slot*.3f),Math.Abs(b));if(i%Math.Max(1,(int)Math.Ceiling(Names.Count/8.0))==0)g.DrawString(Names[i],font,Brushes.DimGray,x,baseline+5);}g.DrawString("Taller (azul) · Mostrador (verde). Importes diarios; negativos bajo el eje.",font,Brushes.DimGray,30,Height-18);}}}
 protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);if(!Daily||Names.Count==0)return;int index=(int)((e.X-35)/Math.Max(1f,(Width-60f)/Names.Count));if(index>=0&&index<Names.Count&&index!=lastTip){lastTip=index;tip.SetToolTip(this,Names[index]+" · Taller "+Money(Actual[index])+" · Mostrador "+Money(Target[index]));}}
 protected override void Dispose(bool disposing){if(disposing)tip.Dispose();base.Dispose(disposing);}
 static string Money(decimal n){return n.ToString("C0",CultureInfo.GetCultureInfo("es-AR"));}
}
