 void RefreshData(){if(changing)return;var snap=store.Get(P);var g=store.GetGoal(P);var all=store.Visible(snap);var accumulated=Filter(all.Where(x=>snap!=null&&x.Date<=snap.Cutoff)).ToList();var selected=Filter(all.Where(x=>x.Date>=from.Value.Date&&x.Date<=to.Value.Date)).ToList();var total=SalesMath.Sum(selected);
 headline.Text="Venta "+M(total.Sale)+"       Utilidad "+M(total.Profit)+"\nMargen real "+N(total.Margin)+" %       Objetivo de margen "+g.Margin.ToString("N2",AR)+" %";
 scope.Text="Indicadores y tickets: "+from.Value.ToString("dd/MM/yyyy")+" al "+to.Value.ToString("dd/MM/yyyy")+" · "+sector.Text+". Avance y proyección: desde el 27 hasta el corte guardado.";
 bars.Names=new List<string>{"Total","Taller","Mostrador"};var full=all.Where(x=>snap!=null&&x.Date<=snap.Cutoff).ToList();bars.Actual=new List<decimal>{full.Sum(x=>x.Sale),full.Where(x=>x.Sector=="Taller").Sum(x=>x.Sale),full.Where(x=>x.Sector=="Mostrador").Sum(x=>x.Sale)};bars.Target=new List<decimal>{g.Total,g.Total*g.Taller/100,g.Total*(100-g.Taller)/100};bars.Invalidate();
 results.Rows.Clear();foreach(string boca in new[]{"Taller","Mostrador"}){var m=SalesMath.Sum(selected.Where(x=>x.Sector==boca));results.Rows.Add(boca,m.Tickets,m.Average.HasValue?M(m.Average.Value):"—",N(m.Margin)+" %");}
 detail.Rows.Clear();foreach(string c in new[]{"Interno","Garantía","Cortesía"}){var lines=snap==null?new List<SaleLine>():Filter(snap.Lines.Where(x=>x.Category==c&&x.Date>=from.Value.Date&&x.Date<=to.Value.Date)).ToList();var m=SalesMath.Sum(lines);bool on=c=="Interno"?store.Intern:c=="Garantía"?store.Warranty:store.Courtesy;detail.Rows.Add(c,on?"Incluido":"Excluido",M(m.Sale),M(m.Profit),lines.Select(x=>x.Key).Distinct().Count());}
